.con-kpi-grid { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: 8px; padding-bottom: 2px; }
@media (max-width: 1023px) { .con-kpi-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); min-width: 96rem; } }
.con-kpi { display: flex; height: 100%; box-sizing: border-box; flex-direction: column; overflow: hidden; padding: 8px; border: 1px solid var(--border-primary); border-radius: 12px; background: var(--surface-card); cursor: pointer; transition: background-color 0.15s, border-color 0.15s; }
.con-kpi:hover { background: var(--surface-hover); }
.con-kpi:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--border-focus); }
.con-kpi.selected, .con-kpi.selected:hover { background: color-mix(in srgb, var(--accent-primary) 15%, transparent); border-color: var(--accent-primary); }
.con-kpi-inner { display: flex; height: 100%; min-height: 108px; flex-direction: column; }
.con-kpi-head { display: flex; min-height: 32px; align-items: flex-start; justify-content: space-between; gap: 4px; }
.con-kpi-title { display: -webkit-box; min-width: 0; flex: 1; overflow: hidden; font-size: 10px; line-height: 1.25; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--text-primary); -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.con-kpi-refresh { display: flex; flex-shrink: 0; align-items: center; justify-content: center; padding: 4px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); color: var(--text-secondary); cursor: pointer; }
