.con-kpi-spacer { min-height: 4px; flex: 1; }
.con-kpi-foot { display: flex; width: 100%; margin-top: 10px; align-items: flex-end; justify-content: space-between; gap: 8px; }
.con-kpi-foot-left { display: flex; min-width: 0; flex-direction: column; align-items: flex-start; gap: 4px; }
.con-kpi-foot-right { display: flex; min-width: 0; flex-direction: column; align-items: flex-end; gap: 4px; text-align: right; }
.con-pill { display: inline; padding: 2px 6px; border-radius: 4px; font-size: 9px; line-height: 1.25; font-weight: 600; }
.con-pill.pilots { background: rgba(59, 130, 246, 0.2); color: #1d4ed8; }
