.con-scope-btn { padding: 2px 8px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); font-family: inherit; font-size: 11px; font-weight: 600; color: var(--accent-primary); cursor: pointer; }
.con-table-shell { overflow-x: auto; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
